fn is_min_heap(a: &Vec<i32>) -> bool {
    let n = a.len();
    // We only need to iterate parents that have at least one child,
    // i.e. indices < n/2.
    for i in 0..n / 2 {
        let left = 2 * i + 1;
        let right = 2 * i + 2;

        // Check left child
        if left < n && a[i] > a[left] {
            return false;
        }
        // Check right child
        if right < n && a[i] > a[right] {
            return false;
        }
    }

    true
}